extern "C" unsigned int strlen(const char *);

struct string_buf { void *data; int ref_count; int char_length; };
class stringx {
    char *chars;
public:
    string_buf *my_buf;
    stringx();
    stringx(const stringx &);
    ~stringx();
    void make_room(int);
    void append(const char *, int = -1);
    void append(const stringx &);
};

inline stringx operator+(const char *lhs, const stringx &rhs) {
    stringx foo;
    int len = strlen(lhs);
    foo.make_room(len + rhs.my_buf->char_length);
    foo.append(lhs, len);
    foo.append(rhs);
    return foo;
}
inline stringx operator+(const stringx &lhs, const stringx &rhs) {
    stringx foo;
    foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
    foo.append(lhs);
    foo.append(rhs);
    return foo;
}
extern void error(const stringx &);

class script_instance { public: stringx name; const stringx &get_name() const { return name; } };
class script_executable { char pad[12]; public: stringx fullname; const stringx &get_fullname() const { return fullname; } };
class vm_thread { script_instance *instance; script_executable *executable; public: script_instance *get_instance() const { return instance; } script_executable *get_executable() const { return executable; } };
class vm_stack {
public:
    int salloc;
    char *buffer;
    char *SP;
private:
    vm_thread *my_thread;
public:
    char *get_SP() const { return SP; }
    vm_thread *get_thread() const { return my_thread; }
    void pop(int n) { SP += -n; }
    bool push(const char *, int);
};

class entity;
template<class T> class vector { public: T *begin_; T *end_; unsigned int size() const { return end_ - begin_; } };
typedef entity *vm_entity_t;
typedef vector<vm_entity_t> entity_list;
