typedef float vm_num_t;

class script_library_class { public: class function { public: enum entry_t { FIRST_ENTRY }; }; };

#define SLF_PARMS stack.pop(sizeof(parms_t)); parms_t* parms = (parms_t*)stack.get_SP()
#define SLF_RETURN if (!stack.push((char*)&result,sizeof(result))) error(stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname())
#define SLF_DONE return true

class slf_entity_list_size_t : public script_library_class::function {
public:
    struct parms_t { vm_entity_list_t me; };
    bool operator()(vm_stack& stack,entry_t entry);
};

bool slf_entity_list_size_t::operator()(vm_stack& stack,entry_t entry)
{
    SLF_PARMS;
    vm_num_t result = parms->me->size();
    SLF_RETURN;
    SLF_DONE;
}

